//#region src/utils/react-compiler-support.ts
/**
* The React Compiler option landed in @vitejs/plugin-react 6.1. Older versions
* accept an unknown `compiler` key in their options object and silently drop
* it, which would leave the compiler disabled while the config says otherwise.
*
* The plugin factory only returns `vite:react-compiler` when the installed
* version understands the option, so its presence is what we probe for.
*/
const REACT_COMPILER_PLUGIN_NAME = "vite:react-compiler";
/** Whether the user asked for the React Compiler through vinext's `react` option. */
function isReactCompilerRequested(reactOptions) {
	if (!reactOptions || typeof reactOptions !== "object") return false;
	return Boolean(reactOptions.compiler);
}
/** Whether a plugin entry is the React Compiler plugin. */
function isReactCompilerPlugin(plugin) {
	return typeof plugin === "object" && plugin !== null && plugin.name === "vite:react-compiler";
}
/** Whether the resolved @vitejs/plugin-react actually registered the compiler. */
function hasReactCompilerPlugin(plugins) {
	return plugins.some(isReactCompilerPlugin);
}
/** Message for when `react: { compiler: true }` cannot be honored. */
function reactCompilerUnsupportedMessage(installCommand) {
	return "vinext: `react: { compiler: true }` requires @vitejs/plugin-react 6.1 or newer.\nThe installed version ignores the option, which would leave the React Compiler disabled.\nRun: " + installCommand + " @vitejs/plugin-react@latest";
}
//#endregion
export { REACT_COMPILER_PLUGIN_NAME, hasReactCompilerPlugin, isReactCompilerPlugin, isReactCompilerRequested, reactCompilerUnsupportedMessage };
